var inorderSuccessor = function(root, p) {
    let successor = null;

    while (root) {
        if (p.val < root.val) {
            // root could be the successor (it is greater than p)
            // but there might be something smaller in the left subtree
            successor = root;
            root = root.left;
        } else {
            // root.val <= p.val, so successor must be in the right subtree
            root = root.right;
        }
    }

    return successor;
};
